<?php if (!defined('BASEPATH')) exit('No direct script access allowed');class Mlab extends CI_Controller {    public function __construct() {        parent::__construct();        $this->load->model(CNFCOMPANY . "mlabmodel");        $this->load->helper('xssclean');        fnIfCheckUserLoggedIn();        $this->limit = LIMITPERPAGE;        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $this->companyid = $ArrUserLoggedInfo['companyid'];        $this->userid = $ArrUserLoggedInfo['id'];    }    public function addedit() {        $ArrData = array('ArrBasicInfo' => array(), 'VarId' => '');        $VarId = base64_decode(urldecode($this->uri->segment(4)));        $ArrData['Edit'] = $this->uri->segment(5);        if (is_numeric($VarId)) {            $ArrResults = $this->mlabmodel->fnGetLabInfo('', '', $VarId, $this->companyid);            $ArrData['ArrBasicInfo'] = $ArrResults[0];            $ArrData['VarId'] = $ArrResults[0]['id'];        } else {        }        $this->load->view(CNFCOMPANY . 'addeditlab', $ArrData);    }    public function updateLabInfo() {        $ArrResult = array();        $VarLabName = xssclean($this->input->post('ln'));        $VarStatus = xssclean($this->input->post('s'));        $VarId = xssclean($this->input->post('id'));        if ($VarLabName <> '') {            $ArrUpdateData = array('id' => $VarId, 'labname' => $VarLabName, 'companyid' => $this->companyid, 'status' => $VarStatus,                'updatedby' => $this->userid, 'dateupdated' => date('Y-m-d H:i:s'));            if ($VarId == '' || $VarId == 0) {                $ArrUpdateData['datecreated'] = date('Y-m-d H:i:s');            }            $ArrResult = $this->mlabmodel->saveLabInfo($ArrUpdateData);        } else {            $ArrResult['errcode'] = -1;            $ArrResult['msg'] = 'Invalid Input';        }        echo json_encode($ArrResult);    }    public function managelab() {        $VarFrom = xssclean($this->input->post('rfrom'));        $VarLabName = trim(xssclean($this->input->post('ln')));        $VarStatus = xssclean($this->input->post('s'));        $clickedColumnId = xssclean($this->input->post('columnId'));        $newsortorder = xssclean($this->input->post('sortorder'));        $VarAfilter = xssclean($this->input->post('afilter'));        $ArrDbCols = array('ln.labname', 'ln.status', 'u.contactname', 'ln.dateupdated');        if ($VarFrom == 1) {            $VarURLSegment = 4;            $this->load->library('pagination');            $config['base_url'] = base_url() . CNFCOMPANY . 'mlab/managelab/';            $config['total_rows'] = $this->mlabmodel->fnCountLab($VarLabName, $VarStatus, $VarAfilter);            $config['per_page'] = $this->limit;            $config['uri_segment'] = $VarURLSegment;            $offset = $this->uri->segment($VarURLSegment);            $this->pagination->initialize($config);            $sortby = "dateupdated";            $sortorder = "desc";            if ($clickedColumnId <> '' && $newsortorder <> '') {                if (array_key_exists($clickedColumnId, $ArrDbCols)) {                    $sortby = $ArrDbCols[$clickedColumnId];                }                $sortorder = $newsortorder;            }            $ArrLabList = $this->mlabmodel->fnListLab($VarLabName, $VarStatus, $this->limit, $offset, $sortby, $sortorder, $VarAfilter)->result();            $data['pagination'] = $this->pagination->create_linkswithajax('Lab');            $i = 0;            $ArrFnlList = array();            $ArrStatus = unserialize(ARRSTATUS);            foreach ($ArrLabList as $ObjUnit) {                $ArrFnlList[$i]['id'] = $ObjUnit->id;                $ArrFnlList[$i]['n'] = $ObjUnit->labname;                $ArrFnlList[$i]['ub'] = $ObjUnit->contactname;                $ArrFnlList[$i]['s'] = $ArrStatus[$ObjUnit->status];                $ArrFnlList[$i]['du'] = date('d-m-Y H:i A', strtotime($ObjUnit->dateupdated));                $i = $i + 1;            }            echo json_encode(array('errcode' => 1, 'cn' => $config['total_rows'], 'ct' => $i, 're' => $ArrFnlList, 'pa' => base64_encode($data['pagination'])));            unset($ArrFnlList);            die;        } else {            $this->load->view(CNFCOMPANY . 'managelab');        }    }    function changemStatus() {        $VarActDeactOption = xssclean($this->input->post('actDeact'));        $VarCid = xssclean($this->input->post('cid'));        if ($VarActDeactOption <> '' && $VarCid <> '') {            $this->mlabmodel->fnChangeComStat($VarCid, $VarActDeactOption);        }        echo json_encode(array('errcode' => 1));        die;    }}